import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Dashboard — Advanced & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"dashboard-03-advanced-and-customization.md","filePath":"dashboard-03-advanced-and-customization.md"}'),s={name:"dashboard-03-advanced-and-customization.md"};function i(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="dashboard-—-advanced-customization" tabindex="-1">Dashboard — Advanced &amp; Customization <a class="header-anchor" href="#dashboard-—-advanced-customization" aria-label="Permalink to &quot;Dashboard — Advanced &amp; Customization&quot;">​</a></h1><p><em>Understanding each column in depth and using the Dashboard as a daily workflow tool</em></p><hr><h2 id="what-each-column-contains" tabindex="-1">What Each Column Contains <a class="header-anchor" href="#what-each-column-contains" aria-label="Permalink to &quot;What Each Column Contains&quot;">​</a></h2><h3 id="collecting-data" tabindex="-1">Collecting Data <a class="header-anchor" href="#collecting-data" aria-label="Permalink to &quot;Collecting Data&quot;">​</a></h3><p>Shows the 8 most recently created Extracts and the 4 most recently updated Competitive Intelligence reports. This column fills when:</p><ul><li>Transcripts are imported (manually or via Fireflies, Gong, or another integration) and features are extracted</li><li>Competitive Intelligence reports are generated</li></ul><p>A full Collecting Data column means there&#39;s signal coming in. An empty one means transcripts haven&#39;t been processed recently.</p><h3 id="processing-data" tabindex="-1">Processing Data <a class="header-anchor" href="#processing-data" aria-label="Permalink to &quot;Processing Data&quot;">​</a></h3><p>Shows the 20 most recently created or updated documents attached to backlog items — PRDs, Opportunity Canvases, User Stories, UAT Test Plans, User Guides, prototypes, and announcement content. This column fills when your team is actively writing and generating documents for features.</p><p>Items in this column also show a document violation flag if the feature&#39;s document rules are not satisfied. This is visible as a distinct color on the type badge.</p><h3 id="making-plans" tabindex="-1">Making Plans <a class="header-anchor" href="#making-plans" aria-label="Permalink to &quot;Making Plans&quot;">​</a></h3><p>Shows up to 6 recently updated Roadmaps, 6 Strategies, and 6 Feature Auctions. This column reflects active planning activity. A roadmap that hasn&#39;t been touched recently drops out of the dashboard view; one that&#39;s actively being edited or restructured stays visible.</p><h3 id="aligning-plans" tabindex="-1">Aligning Plans <a class="header-anchor" href="#aligning-plans" aria-label="Permalink to &quot;Aligning Plans&quot;">​</a></h3><p>Shows the 10 most recent export and sharing events — every time a Roadmap, Strategy, Competitive Intelligence report, or Financial Forecast was exported or shared. This is the column that tracks what has left Lodestone and gone to stakeholders.</p><p>Each row shows:</p><ul><li>What was exported (Roadmap, Strategy, etc.)</li><li>The format it was exported as (PNG, PPT, MD)</li><li>Who it was shared with, if applicable</li><li>A &quot;Newer version available&quot; warning if the source has been updated since the export</li></ul><p>Use this column to maintain the discipline of always sharing current artifacts. If something here shows a warning, your stakeholders may be looking at old information.</p><h3 id="executing-plans" tabindex="-1">Executing Plans <a class="header-anchor" href="#executing-plans" aria-label="Permalink to &quot;Executing Plans&quot;">​</a></h3><p>Shows active features (those in &quot;In Progress&quot; or &quot;Completed&quot; status, up to 10), up to 5 active releases, 4 recently updated Release Notes, and 6 recently updated Bento Grids. This is the execution pulse of your workspace — what&#39;s actively in flight and what has recently shipped.</p><hr><h2 id="using-the-dashboard-as-a-daily-check-in" tabindex="-1">Using the Dashboard as a Daily Check-In <a class="header-anchor" href="#using-the-dashboard-as-a-daily-check-in" aria-label="Permalink to &quot;Using the Dashboard as a Daily Check-In&quot;">​</a></h2><p>A simple daily workflow:</p><ol><li><strong>Open the Dashboard</strong> — check the new-item count to see what changed since yesterday</li><li><strong>Scan Collecting Data</strong> — new extracts mean there are unreviewed product signals; go to Extracts if the count is high</li><li><strong>Check Aligning Plans</strong> — look for &quot;Newer version available&quot; warnings before any scheduled stakeholder meetings</li><li><strong>Review Executing Plans</strong> — spot features that are stuck (haven&#39;t moved to Completed despite being In Progress for a while)</li></ol><p>The Dashboard is most useful as a 60-second orientation tool. It doesn&#39;t replace going into individual modules for detailed work — it tells you where to go first.</p><hr><h2 id="what-the-dashboard-does-not-show" tabindex="-1">What the Dashboard Does Not Show <a class="header-anchor" href="#what-the-dashboard-does-not-show" aria-label="Permalink to &quot;What the Dashboard Does Not Show&quot;">​</a></h2><p>The Dashboard is a recent-activity view, not a complete inventory. It shows a limited number of items per column, sorted by recency. Objects that haven&#39;t been updated recently don&#39;t appear, even if they exist. For a complete list of any object type, navigate to its module directly.</p><p>The Dashboard also does not show:</p><ul><li>Customer quotes</li><li>Individual evaluation scores or RICE rankings</li><li>Financial Forecast models</li><li>MFA or security settings</li></ul><hr><p><em>Next: Troubleshooting &amp; FAQs — common questions about what appears in the Dashboard and why.</em></p>',32)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
